function escapeXml(s: string): string {
  return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;');
}
function parseXml(xml: string): Document {
  const d = new DOMParser().parseFromString(xml,'application/xml');
  if (d.getElementsByTagName('parsererror').length) throw new Error('Alma returned invalid XML');
  return d;
}
function parseResult(result: any): any {
  if (typeof result === 'string' && result.trim().startsWith('<')) return parseXml(result);
  return result;
}
function valueOf(result: any, tag: string): string {
  const r=parseResult(result);
  if(r?.nodeType === 9) return (r.getElementsByTagName(tag)[0]?.textContent || '').trim();
  if (r && typeof r === 'object') {
    if (r[tag] !== undefined) {
      const v=r[tag]; return typeof v==='object' ? String(v?.value ?? v?.['#text'] ?? '') : String(v ?? '');
    }
    for(const child of Object.values(r)){ if (child && typeof child==='object') { const found=valueOf(child,tag); if(found) return found; } }
  }
  return '';
}
function jobInstanceId(result: any): string {
  const r=parseResult(result);
  if(r?.nodeType === 9) {
    const link=(r.getElementsByTagName('additional_info')[0] as Element)?.getAttribute('link')||'';
    return link.match(/\/instances\/(\d+)/)?.[1] || valueOf(r,'id');
  }
  const link=String(r?.additional_info?.link ?? r?.additional_info?.['@link'] ?? r?.job_instance?.link ?? '');
  return link.match(/\/instances\/(\d+)/)?.[1] || String(r?.job_instance?.id ?? r?.id ?? '');
}
function buildM18(xmlTemplate: string, edits: Record<string,string>, expectedSelected: string): string {
  const document = parseXml(xmlTemplate);
  const parameters = Array.from(document.getElementsByTagName('parameter'));
  const map=new Map<string,Element>();
  for(const parameter of parameters) {
    const name=(parameter.getElementsByTagName('name')[0]?.textContent||'').trim();
    if(!name || map.has(name)) throw new Error('Duplicated/missing M18 parameter: '+name);
    const v=parameter.getElementsByTagName('value')[0];
    if(!v) throw new Error('M18 parameter missing value: '+name);
    map.set(name,v);
  }
  for(const [k,v] of Object.entries(edits)){
    const el=map.get(k);
    if(!el)throw new Error('M18 parameter not in template: '+k);
    el.textContent=v;
  }
  const selected=Array.from(map.keys()).filter(k=>k.endsWith('_selected') && map.get(k)?.textContent?.trim() === 'true').sort();
  const expected=expectedSelected.split(',').sort();
  if(selected.join(',')!==expected.join(',')) throw new Error('M18 includes unexpected active changes: '+selected.join(', '));
  if(expectedSelected==='PERMANENT_LIBRARY_LOCATION_selected') {
    for(const key of ['WEEDING_DATE_selected','WEEDING_NUMBER_selected','IN_PROCESS_TYPE_selected','DEPARTMENT_selected'])
      if(map.get(key)?.textContent?.trim()!=='false') throw new Error('Move attempts to edit '+key);
    if(map.get('WEEDING_DATE_condition')?.textContent?.trim()!=='Null' || map.get('WEEDING_DATE_value')?.textContent?.trim()!=='0')
      throw new Error('Move template contains stale date parameters');
    if(map.has('WEEEDING_NUMBER_SEQ_value') && map.get('WEEEDING_NUMBER_SEQ_value')?.textContent?.trim()!=='Null')
      throw new Error('Move template contains a weeding number sequence');
  }
  return new XMLSerializer().serializeToString(document);
}
