export function createWoPayload(setId:string,setName:string,departmentId:string,targetWorkOrder:string):string {
  if(!/^\d{10,}$/.test(setId) || !/^\d{10,}$/.test(departmentId) || !/^[A-Za-z0-9_-]+$/.test(targetWorkOrder))
    throw new Error('Invalid M18 WO set, department ID or target code');
  return buildM18(TEMPLATE_WO,{
    set_id:setId,job_name:'ODP-WO-'+setName,
    DEPARTMENT_value:departmentId, IN_PROCESS_TYPE_value:targetWorkOrder,
  },'DEPARTMENT_selected,IN_PROCESS_TYPE_selected');
}
export function createNumberPayload(setId: string, setName: string, targetLocationId: string, sequenceName: string, dateEpochMs: number): string {
  if(!/^\d{10,}$/.test(setId) || !/^\d{10,}$/.test(targetLocationId) || !sequenceName.trim()) throw new Error('Invalid set/location/sequence');
  if(!Number.isFinite(dateEpochMs) || dateEpochMs<1) throw new Error('Invalid date');
  const payload=buildM18(TEMPLATE_NUMBER,{
    set_id:setId,
    job_name:'ODP-Odpis-'+setName,
    PERMANENT_LIBRARY_LOCATION_value:targetLocationId,
    WEEEDING_NUMBER_SEQ_value:sequenceName,
    WEEDING_DATE_value:String(dateEpochMs),
  },'PERMANENT_LIBRARY_LOCATION_selected,WEEDING_DATE_selected');
  return payload;
}
export function createMovePayload(setId: string, setName: string, targetLocationId: string): string {
  if(!/^\d{10,}$/.test(setId) || !/^\d{10,}$/.test(targetLocationId)) throw new Error('Invalid set/location');
  return buildM18(TEMPLATE_MOVE,{
    set_id:setId, job_name:'ODP-Presun-'+setName,
    PERMANENT_LIBRARY_LOCATION_value:targetLocationId,
  },'PERMANENT_LIBRARY_LOCATION_selected');
}
export class WeedingAlmaApi {
  constructor(private rest:CloudAppRestService) {}
  private async get(path:string):Promise<any>{return firstValueFrom(this.rest.call<any>(path));}
  private async postXml(path:string,xml:string):Promise<any>{
    return firstValueFrom(this.rest.call<any>({url:path,method:HttpMethod.POST,
      headers:{'Content-Type':'application/xml','Accept':'application/xml'} as any,requestBody:xml}));
  }
  async listWorkOrderDepartments():Promise<{id:string;code:string;name:string}[]>{
    const r:any=await this.get('/almaws/v1/conf/departments?view=brief&format=json');
    const raw=r?.department??r?.departments?.department??[];
    const list=Array.isArray(raw)?raw:(raw?[raw]:[]);
    return list.map((d:any)=>({
      id:String(d?.id??d?.department_id??''),
      code:String(d?.code??''),
      name:String(d?.name??d?.description??d?.code??'')
    })).filter((d:{id:string})=>/^\d{10,}$/.test(d.id));
  }
  async getSetDetail(setId:string):Promise<any>{
    if(!/^\d{10,}$/.test(setId))throw new Error('Neplatné Set ID');
    const result:any=await this.get(`/almaws/v1/conf/sets/${encodeURIComponent(setId)}?format=json`);
    return result?.set??result;
  }
  async updateSetMetadata(setId:string,description:string,note:string):Promise<any>{
    // Alma PUT is full-replacement: fetch the whole object, preserve all unrelated fields.
    const original=await this.getSetDetail(setId);
    if(String(original?.id??'')!==setId || String(original?.type?.value??original?.type??'').toUpperCase()!=='ITEMIZED')
      throw new Error('Získaný set nemá očekávané ID nebo typ ITEMIZED');
    const before=await this.members(setId);
    const updated={...original,description,note};
    await firstValueFrom(this.rest.call<any>({url:`/almaws/v1/conf/sets/${encodeURIComponent(setId)}?format=json`,
      method:HttpMethod.PUT,headers:{'Content-Type':'application/json','Accept':'application/json'} as any,
      requestBody:JSON.stringify(updated)}));
    const after=await this.members(setId);
    if(before.length!==after.length||before.sort().some((x,i)=>x!==after.sort()[i]))
      throw new Error('KRITICKÉ: po aktualizaci metadat se změnilo členství setu. Neprovádějte žádný job!');
    const checked=await this.getSetDetail(setId);
    if(String(checked?.description??'')!==description||String(checked?.note??'')!==note)
      throw new Error('Alma nepotvrdila změnu metadat setu');
    return checked;
  }
  async locationId(library:string,location:string):Promise<string>{
    const r:any=await this.get(`/almaws/v1/conf/libraries/${encodeURIComponent(library)}/locations/${encodeURIComponent(location)}?format=json`);
    const id=String(r?.id ?? r?.location?.id ?? '');
    if(!/^\d+$/.test(id))throw new Error('Alma did not return an internal location ID');
    return id;
  }
  /** The query below was validated in PSB (18/18 identical item PIDs).
   * Logical sets are only a discovery mechanism; M18 must run over ITEMIZED sets.
   */
  async createDiscoverySet(library:string,location:string,workOrderType:string):Promise<string>{
    for(const [label,value] of [['knihovna',library],['lokace',location],['Work Order',workOrderType]] as [string,string][]){
      if(!/^[A-Za-z0-9_-]+$/.test(value))throw new Error('Neplatná hodnota '+label);
    }
    const query=`ITEM where HOLDING (permanentPhysicalLocation OUTER_EQUAL "${library} : ${location}") AND ITEM (statisticsNote2 NOT_EMPTY) AND ITEM (inProcessType OUTER_EQUAL "${workOrderType}")`;
    const name=`ODP-DISCOVERY-${library}-${location}-${Date.now()}`;
    const xml=`<set><name>${escapeXml(name)}</name><type>LOGICAL</type><content>ITEM</content><private>true</private><query>${escapeXml(query)}</query></set>`;
    const response=await this.postXml('/almaws/v1/conf/sets',xml);
    const id=valueOf(response,'id');
    if(!/^\d{10,}$/.test(id))throw new Error('Vytvoření pomocného setu má nejasný výsledek – POST neopakujte, zkontrolujte sety v Almě.');
    return id;
  }
  async discoveryMembers(setId:string):Promise<string[]>{
    const detail=await this.getSetDetail(setId);
    if(String(detail?.id||'')!==setId||String(detail?.type?.value??detail?.type??'').toUpperCase()!=='LOGICAL'||String(detail?.content?.value??detail?.content??'').toUpperCase()!=='ITEM')
      throw new Error('Pomocný set nemá očekávaný typ LOGICAL / ITEM');
    const expected=Number(detail?.number_of_members?.value??detail?.number_of_members);
    if(!Number.isSafeInteger(expected)||expected<0)throw new Error('Alma nevrátila počet členů pomocného setu');
    const ids=await this.members(setId);
    if(ids.length!==expected||new Set(ids).size!==ids.length||ids.some(id=>!/^\d{8,25}$/.test(id)))
      throw new Error(`Neúplné nebo duplicitní členství pomocného setu: ${ids.length}/${expected}`);
    return ids;
  }
  async deleteDiscoverySet(setId:string):Promise<void>{
    const detail=await this.getSetDetail(setId);
    if(!String(detail?.name||'').startsWith('ODP-DISCOVERY-') || String(detail?.type?.value??detail?.type??'').toUpperCase()!=='LOGICAL')
      throw new Error('Mazání nepovoleno: nejde o pomocný logický set aplikace');
    await firstValueFrom(this.rest.call<any>({url:`/almaws/v1/conf/sets/${encodeURIComponent(setId)}`,method:HttpMethod.DELETE}));
  }
  async createSet(name:string,description:string):Promise<string>{
    const xml=`<set><name>${escapeXml(name)}</name><description>${escapeXml(description)}</description><type>ITEMIZED</type><content>ITEM</content><private>false</private><status>ACTIVE</status><origin>UI</origin></set>`;
    const result=await this.postXml('/almaws/v1/conf/sets',xml);
    const id=valueOf(result,'id');
    if(!/^\d{10,}$/.test(id)) throw new Error('Set may have been created, but response did not contain its ID. Do not retry blindly.');
    return id;
  }
  async addSetMembers(setId:string,memberIds:string[]):Promise<void>{
    if(!/^\d{10,}$/.test(setId))throw new Error('Bad set ID');
    if(memberIds.length>1000)throw new Error('Set member chunk exceeds 1000');
    if(!memberIds.length)return;
    const members=memberIds.map(id=>`<member><id>${escapeXml(id)}</id></member>`).join('');
    await this.postXml(`/almaws/v1/conf/sets/${encodeURIComponent(setId)}?op=add_members`, `<set><members>${members}</members></set>`);
  }
  async setByExactName(name:string):Promise<{id:string;name:string}[]>{
    // Search all pages. Never assume the last page is the first matching set.
    const matching:{id:string;name:string}[]=[];let offset=0;
    while(true){
      const r:any=await this.get(`/almaws/v1/conf/sets?set_type=ITEMIZED&content_type=ITEM&limit=100&offset=${offset}&format=json`);
      const raw=r?.set??[];const page=Array.isArray(raw)?raw:(raw?[raw]:[]);
      for(const x of page)if(String(x?.name||'')===name)matching.push({id:String(x?.id||''),name});
      offset+=page.length;
      const total=Number(r?.total_record_count);
      if((Number.isFinite(total)&&offset>=total)||page.length<100)break;
      if(!page.length)throw new Error('Empty set page before expected end');
    }
    return matching;
  }
  async members(setId:string):Promise<string[]>{
    const ids:string[]=[];let offset=0;
    while(true){
      const r:any=await this.get(`/almaws/v1/conf/sets/${encodeURIComponent(setId)}/members?limit=100&offset=${offset}&format=json`);
      const list=Array.isArray(r?.member)?r.member:(r?.members?.member??r?.set?.members?.member??[]);
      const page=Array.isArray(list)?list:(list?[list]:[]);
      ids.push(...page.map((x:any)=>String(x.id||'')).filter(Boolean));
      offset+=page.length;
      const total=Number(r?.total_record_count ?? r?.members?.total_record_count);
      if(Number.isFinite(total)&&offset>=total)break;
      if(page.length<100)break;
      if(!page.length)throw new Error('Invalid empty set members page');
    }
    return ids;
  }
  async verifyMembers(setId:string,expected:string[]):Promise<void>{
    const actual=(await this.members(setId)).sort();
    const wanted=[...expected].sort();
    if(actual.length!==wanted.length || actual.some((id,i)=>id!==wanted[i])) throw new Error('Set membership does not match the selected items');
  }
  async getItem(pid:string):Promise<any>{
    return this.get(`/almaws/v1/bibs/1/holdings/2/items/${encodeURIComponent(pid)}?format=json`);
  }
  async runM18(payload:string):Promise<string>{
    const result=await this.postXml('/almaws/v1/conf/jobs/M18?op=run',payload);
    const id=jobInstanceId(result);
    if(!/^\d{10,}$/.test(id))throw new Error('M18 request may have been accepted, but the instance ID is unknown. DO NOT resubmit.');
    return id;
  }
  async jobStatus(instance:string):Promise<string>{
    const r=await this.get(`/almaws/v1/conf/jobs/M18/instances/${encodeURIComponent(instance)}?format=json`);
    return String((r as any)?.job_instance?.status?.value ?? (r as any)?.job_instance?.status ?? (r as any)?.status?.value ?? (r as any)?.status ?? valueOf(r,'status') ?? '');
  }
  async validateScanner(library:string, woCode:string, mode:'circ_desk'|'department',code:string):Promise<void>{
    if(!code || !/^[A-Za-z0-9_-]+$/.test(code))throw new Error('Scan-in configuration has no valid desk/department code');
    if(mode==='circ_desk'){
      const r:any=await this.get(`/almaws/v1/conf/libraries/${encodeURIComponent(library)}/circ-desks/${encodeURIComponent(code)}?format=json`);
      const desk=r?.circ_desk||r;
      if(String(desk?.code||'')!==code)throw new Error('Requested circulation desk not confirmed by Alma API: '+code);
      const raw=desk?.work_order_type;
      const values:any[]=Array.isArray(raw)?raw:(raw?[raw]:[]);
      const codes=values.map(x=>String(x?.work_order_type_code?.value??x?.work_order_type_code??x?.value??x??''));
      if(!codes.some(x=>x===woCode||x.endsWith('-'+woCode)))
        throw new Error('Circulation desk does not have the requested work order '+woCode);
    }else{
      const r:any=await this.get('/almaws/v1/conf/departments?view=brief&format=json');
      const raw=r?.department??r?.departments?.department??[];
      const list=Array.isArray(raw)?raw:(raw?[raw]:[]);
      if(!list.some(x=>String(x?.code||'')===code))throw new Error('Requested department not found: '+code);
    }
  }
  async scanIn(pid:string, mmsId:string, holdingId:string, library:string, woCode:string, mode:'circ_desk'|'department',code:string):Promise<void>{
    const args=new URLSearchParams({op:'scan',library,work_order_type:woCode,confirm:'false',register_in_house_use:'false'});
    args.set(mode,code);
    if(mode==='department')args.set('done','false');
    await this.postXml(`/almaws/v1/bibs/${encodeURIComponent(mmsId)}/holdings/${encodeURIComponent(holdingId)}/items/${encodeURIComponent(pid)}?${args.toString()}`, '');
  }
  async findHistoricalSets(prefix='ODP-'):Promise<{id:string;name:string}[]>{
    const result:{id:string;name:string}[]=[];let offset=0;
    while(true){
      const r:any=await this.get(`/almaws/v1/conf/sets?set_type=ITEMIZED&content_type=ITEM&limit=100&offset=${offset}&format=json`);
      const entries=Array.isArray(r?.set)?r.set:(r?.set?[r.set]:[]);
      for(const s of entries){const name=String(s?.name||'');if(name.startsWith(prefix))result.push({id:String(s?.id||''),name});}
      offset+=entries.length;const total=Number(r?.total_record_count);
      if((Number.isFinite(total)&&offset>=total)||entries.length<100)break;
      if(!entries.length)break;
    }
    return result;
  }
}
